import { desc, sql } from 'drizzle-orm';
import {
  check,
  foreignKey,
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
} from 'drizzle-orm/sqlite-core';
import type {
  VariantHistoryManifest,
  VariantHistorySessionFile,
  VariantHistoryStatus,
} from '../../../types/variant-history';

type VariantDetails = Omit<
  VariantHistoryManifest,
  | 'sessionId'
  | 'variantId'
  | 'label'
  | 'brief'
  | 'status'
  | 'createdAt'
  | 'statusChangedAt'
  | 'changedFilesCount'
  | 'tree'
  | 'base'
  | 'parent'
  | 'parentVariant'
>;

export const project = sqliteTable(
  'project',
  {
    singleton: integer().primaryKey(),
    id: text().notNull().unique(),
    name: text().notNull(),
    createdAt: text('created_at').notNull(),
    updatedAt: text('updated_at').notNull(),
  },
  (table) => [check('project_singleton', sql`${table.singleton} = 1`)],
);

export const sessions = sqliteTable('sessions', {
  id: text().primaryKey(),
  initialPrompt: text('initial_prompt').notNull(),
  projectKind: text('project_kind')
    .$type<VariantHistoryManifest['projectKind']>()
    .notNull(),
  sourceWorkspaceId: text('source_workspace_id'),
  createdAt: text('created_at').notNull(),
  contextPath: text('context_path'),
  details: text('details_json', { mode: 'json' })
    .$type<Partial<VariantHistorySessionFile>>()
    .notNull(),
});

export const batches = sqliteTable(
  'batches',
  {
    id: text().notNull(),
    sessionId: text('session_id')
      .notNull()
      .references(() => sessions.id),
    requestId: text('request_id'),
    label: text(),
    instruction: text(),
    createdAt: text('created_at').notNull(),
    contextPath: text('context_path'),
  },
  (table) => [primaryKey({ columns: [table.sessionId, table.id] })],
);

export const snapshots = sqliteTable('snapshots', {
  id: text().primaryKey(),
  gitRef: text('git_ref').notNull(),
  commitSha: text('commit_sha').notNull(),
  treeSha: text('tree_sha'),
  createdAt: text('created_at').notNull(),
});

export const variants = sqliteTable(
  'variants',
  {
    sessionId: text('session_id')
      .notNull()
      .references(() => sessions.id),
    variantId: text('variant_id').notNull(),
    batchId: text('batch_id').notNull(),
    label: text().notNull(),
    brief: text().notNull(),
    status: text().$type<VariantHistoryStatus>().notNull(),
    createdAt: text('created_at').notNull(),
    statusChangedAt: text('status_changed_at').notNull(),
    snapshotId: text('snapshot_id').references(() => snapshots.id),
    baseSnapshotId: text('base_snapshot_id').references(() => snapshots.id),
    parentSnapshotId: text('parent_snapshot_id').references(() => snapshots.id),
    parentSessionId: text('parent_session_id'),
    parentVariantId: text('parent_variant_id'),
    changedFilesCount: integer('changed_files_count').notNull(),
    artifactPath: text('artifact_path'),
    details: text('details_json', { mode: 'json' })
      .$type<VariantDetails>()
      .notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.sessionId, table.variantId] }),
    foreignKey({
      columns: [table.sessionId, table.batchId],
      foreignColumns: [batches.sessionId, batches.id],
    }),
    index('variants_created_at').on(desc(table.createdAt)),
    index('variants_status').on(table.status),
  ],
);

export const presentation = sqliteTable('presentation', {
  key: text().primaryKey(),
  value: text('value_json').notNull(),
  updatedAt: text('updated_at').notNull(),
});
